'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Axis = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Axis, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var axis;
	var ctor;

	ctor = Axis;
	axis = ctor({
		'scale': 'xScale',
		'orient': 'bottom'
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var axis;
	var ctor;

	ctor = Axis;
	axis = ctor({
		'scale': 'xScale',
		'orient': 'bottom',
		'grid': true
	});
	t.strictEqual( instanceOf( axis, Axis ), true, 'returns expected value' );
	t.strictEqual( axis.grid, true, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var axis = new Axis( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor throws an error if not provided a `scale` option', function test( t ) {
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		var axis = new Axis({ // eslint-disable-line no-unused-vars
			'orient': 'bottom'
		});
	}
});

