tape( 'the constructor ignores unrecognized options', function test( t ) {
	var axis;

	axis = new Axis({
		'scale': 'xScale',
		'orient': 'bottom',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( axis.scale, 'xScale', 'returns expected value' );
	t.strictEqual( axis.beep, void 0, 'returns expected value' );
	t.strictEqual( axis.foo, void 0, 'returns expected value' );

	t.end();
});
